mapper.select:
select * from major_hazard



order by id desc
limit #{offset}, #{limit}

select * from major_hazard
where tenant_id = #{tenantId}
  and hazard_no = #{hazardNo}
  and deleted = 0
limit 1

select distinct h.* from major_hazard h
left join major_hazard_point_rel p
  on p.tenant_id = h.tenant_id and p.hazard_id = h.id and p.deleted = 0
where h.tenant_id = #{tenantId}
  and h.deleted = 0
  and h.status != 'DRAFT'
  and (


        or h.area_id = #{areaId}


        or h.unit_id = #{unitId}


        or p.monitor_point_id in

          #{pointId}



  )
order by h.id asc
